<script setup lang="ts">
import { ref } from 'vue'
import { Delete, Plus } from '@element-plus/icons-vue'

const props = defineProps<{ container: Record<string, any>; volumes: Array<Record<string, any>> }>()
const activeTab = ref('basic')
const envTab = ref('plain')
props.container.resources ??= {}
props.container.resources.requests ??= {}
props.container.resources.limits ??= {}

function list(name: string) { return props.container[name] ?? (props.container[name] = []) }
function references(kind: 'configMapRef' | 'secretRef') { return list('envFrom').filter((item: any) => item[kind]) }
function addReference(kind: 'configMapRef' | 'secretRef') { list('envFrom').push({ [kind]: { name: '', optional: false } }) }
function removeReference(item: any) { const index = list('envFrom').indexOf(item); if (index >= 0) list('envFrom').splice(index, 1) }
function enableProbe(name: string, enabled: boolean) {
  if (enabled) props.container[name] = { httpGet: { path: '/', port: 80 }, initialDelaySeconds: 10, periodSeconds: 10 }
  else delete props.container[name]
}
function probeType(probe: Record<string, any>) { return probe.httpGet ? 'httpGet' : probe.tcpSocket ? 'tcpSocket' : 'exec' }
function changeProbeType(probe: Record<string, any>, type: string) { delete probe.httpGet; delete probe.tcpSocket; delete probe.exec; if(type==='httpGet')probe.httpGet={path:'/',port:80,scheme:'HTTP'};else if(type==='tcpSocket')probe.tcpSocket={port:80};else probe.exec={command:[]} }
function setProbePort(probe: Record<string, any>, value: number | undefined) { (probe.httpGet || probe.tcpSocket).port = value }
function setExecCommand(probe: Record<string, any>, value: string) { probe.exec.command = value.trim() ? value.trim().split(/\s+/) : [] }
</script>

<template>
  <el-tabs v-model="activeTab" class="container-tabs">
    <el-tab-pane label="基础配置" name="basic"><div class="config-grid"><label>容器名称<el-input v-model="container.name"/></label><label>拉取策略<el-select v-model="container.imagePullPolicy"><el-option label="IfNotPresent - 本地不存在时拉取" value="IfNotPresent"/><el-option label="Always - 始终拉取" value="Always"/><el-option label="Never - 从不拉取" value="Never"/></el-select></label><label class="wide">容器镜像<el-input v-model="container.image"/></label><label>工作目录<el-input v-model="container.workingDir" clearable/></label><label>交互终端<el-switch v-model="container.tty"/></label></div></el-tab-pane>
    <el-tab-pane label="运行命令" name="command"><div class="config-grid one"><label>工作目录<el-input v-model="container.workingDir" placeholder="容器的工作目录，如 /app" clearable/></label><section class="command-card"><header><strong>运行命令 (Command)</strong><el-button link :icon="Plus" @click="list('command').push('')">添加命令</el-button></header><div v-for="(_,index) in list('command')" :key="index" class="indexed-row"><span>{{Number(index)+1}}</span><el-input v-model="container.command[index]"/><el-button link type="danger" :icon="Delete" @click="list('command').splice(Number(index),1)"/></div><el-empty v-if="!list('command').length" description="暂无运行命令" :image-size="34"/></section><section class="command-card"><header><strong>启动参数 (Args)</strong><el-button link :icon="Plus" @click="list('args').push('')">添加参数</el-button></header><div v-for="(_,index) in list('args')" :key="index" class="indexed-row"><span>{{Number(index)+1}}</span><el-input v-model="container.args[index]"/><el-button link type="danger" :icon="Delete" @click="list('args').splice(Number(index),1)"/></div><el-empty v-if="!list('args').length" description="暂无启动参数" :image-size="34"/></section><section class="command-card"><header><strong>交互选项</strong></header><div class="switch-row"><el-checkbox v-model="container.stdin">保持标准输入开启 (stdin)</el-checkbox><el-checkbox v-model="container.tty">分配终端 (TTY)</el-checkbox></div></section></div></el-tab-pane>
    <el-tab-pane label="环境变量" name="env"><el-tabs v-model="envTab" class="env-tabs"><el-tab-pane label="普通变量" name="plain"><div class="list-head"><span>环境变量</span><el-button link :icon="Plus" @click="list('env').push({name:'',value:''})">添加变量</el-button></div><div v-for="(item,index) in list('env')" :key="index" class="list-row"><el-input v-model="item.name" placeholder="变量名"/><span>=</span><el-input v-model="item.value" placeholder="变量值"/><el-button link type="danger" :icon="Delete" @click="list('env').splice(index,1)"/></div><el-empty v-if="!list('env').length" description="暂无普通变量" :image-size="38"/></el-tab-pane><el-tab-pane label="配置映射引用" name="configMap"><div class="list-head"><span>ConfigMap 引用</span><el-button link :icon="Plus" @click="addReference('configMapRef')">添加引用</el-button></div><div v-for="(item,index) in references('configMapRef')" :key="index" class="reference-row"><el-input v-model="item.configMapRef.name" placeholder="ConfigMap 名称"/><el-checkbox v-model="item.configMapRef.optional">可选</el-checkbox><el-button link type="danger" :icon="Delete" @click="removeReference(item)"/></div><el-empty v-if="!references('configMapRef').length" description="暂无 ConfigMap 引用" :image-size="38"/></el-tab-pane><el-tab-pane label="密钥引用" name="secret"><div class="list-head"><span>Secret 引用</span><el-button link :icon="Plus" @click="addReference('secretRef')">添加引用</el-button></div><div v-for="(item,index) in references('secretRef')" :key="index" class="reference-row"><el-input v-model="item.secretRef.name" placeholder="Secret 名称"/><el-checkbox v-model="item.secretRef.optional">可选</el-checkbox><el-button link type="danger" :icon="Delete" @click="removeReference(item)"/></div><el-empty v-if="!references('secretRef').length" description="暂无 Secret 引用" :image-size="38"/></el-tab-pane></el-tabs></el-tab-pane>
    <el-tab-pane label="健康检测" name="health"><div class="probe-list"><section v-for="probe in [{key:'livenessProbe',label:'存活探针 (Liveness Probe)'},{key:'readinessProbe',label:'就绪探针 (Readiness Probe)'},{key:'startupProbe',label:'启动探针 (Startup Probe)'}]" :key="probe.key"><header><strong>{{probe.label}}</strong><el-switch :model-value="Boolean(container[probe.key])" @change="enableProbe(probe.key,Boolean($event))"/></header><template v-if="container[probe.key]"><div class="probe-fields"><label>检测类型<el-select :model-value="probeType(container[probe.key])" @change="changeProbeType(container[probe.key],String($event))"><el-option label="HTTP GET" value="httpGet"/><el-option label="TCP Socket" value="tcpSocket"/><el-option label="Exec Command" value="exec"/></el-select></label><label v-if="container[probe.key].httpGet">路径<el-input v-model="container[probe.key].httpGet.path"/></label><label v-if="container[probe.key].httpGet||container[probe.key].tcpSocket">端口<el-input-number :model-value="(container[probe.key].httpGet||container[probe.key].tcpSocket).port" :min="1" :max="65535" @update:model-value="setProbePort(container[probe.key],$event)"/></label><label v-if="container[probe.key].httpGet">协议<el-select v-model="container[probe.key].httpGet.scheme"><el-option label="HTTP" value="HTTP"/><el-option label="HTTPS" value="HTTPS"/></el-select></label><label v-if="container[probe.key].exec" class="wide">执行命令<el-input :model-value="(container[probe.key].exec.command||[]).join(' ')" @update:model-value="setExecCommand(container[probe.key],$event)"/></label></div><el-collapse><el-collapse-item title="高级设置"><div class="probe-fields"><label>初始延迟<el-input-number v-model="container[probe.key].initialDelaySeconds" :min="0"/></label><label>检测周期<el-input-number v-model="container[probe.key].periodSeconds" :min="1"/></label><label>超时时间<el-input-number v-model="container[probe.key].timeoutSeconds" :min="1"/></label><label>失败阈值<el-input-number v-model="container[probe.key].failureThreshold" :min="1"/></label></div></el-collapse-item></el-collapse></template></section></div></el-tab-pane>
    <el-tab-pane label="资源配置" name="resources"><div class="resource-stack"><section><header>CPU 限制</header><div class="resource-grid"><label>请求 (Request)<el-input v-model="container.resources.requests.cpu" placeholder="如 50m"/></label><label>限制 (Limit)<el-input v-model="container.resources.limits.cpu" placeholder="如 500m"/></label></div></section><section><header>内存限制</header><div class="resource-grid"><label>请求 (Request)<el-input v-model="container.resources.requests.memory" placeholder="如 64Mi"/></label><label>限制 (Limit)<el-input v-model="container.resources.limits.memory" placeholder="如 256Mi"/></label></div></section></div></el-tab-pane>
    <el-tab-pane label="端口配置" name="ports"><div v-for="(item,index) in list('ports')" :key="index" class="port-card"><header><strong>端口 {{Number(index)+1}}</strong><el-button link type="danger" :icon="Delete" @click="list('ports').splice(Number(index),1)">删除</el-button></header><div class="config-grid"><label>容器端口<el-input-number v-model="item.containerPort" :min="1" :max="65535"/></label><label>协议<el-select v-model="item.protocol"><el-option label="TCP" value="TCP"/><el-option label="UDP" value="UDP"/><el-option label="SCTP" value="SCTP"/></el-select></label><label>端口名称<el-input v-model="item.name"/></label><label>主机端口<el-input-number v-model="item.hostPort" :min="1" :max="65535" placeholder="可选"/></label><label class="wide">主机 IP<el-input v-model="item.hostIP" placeholder="可选，绑定到特定主机的 IP 地址"/></label></div></div><el-button class="full-add" plain :icon="Plus" @click="list('ports').push({name:'',containerPort:80,protocol:'TCP'})">添加端口</el-button><el-empty v-if="!list('ports').length" description="暂无端口" :image-size="38"/></el-tab-pane>
    <el-tab-pane label="存储挂载" name="mounts"><div class="list-head"><span>卷挂载配置</span><el-button link :icon="Plus" @click="list('volumeMounts').push({name:'',mountPath:'',subPath:'',readOnly:false})">添加挂载点</el-button></div><div class="mount-head"><span>卷名</span><span>挂载路径</span><span>子路径</span><span>只读</span><span>操作</span></div><div v-for="(item,index) in list('volumeMounts')" :key="index" class="mount-row"><el-select v-model="item.name" placeholder="数据卷"><el-option v-for="volume in volumes" :key="volume.name" :label="volume.name" :value="volume.name"/></el-select><el-input v-model="item.mountPath" placeholder="挂载路径"/><el-input v-model="item.subPath" placeholder="可选，卷内子路径"/><el-switch v-model="item.readOnly"/><el-button link type="danger" :icon="Delete" @click="list('volumeMounts').splice(index,1)"/></div><el-empty v-if="!list('volumeMounts').length" description="暂无存储挂载" :image-size="38"/></el-tab-pane>
  </el-tabs>
</template>

<style scoped>
.container-tabs{padding:0 10px 10px;font-size:10px}.container-tabs :deep(.el-tabs__header){margin:0 0 8px}.container-tabs :deep(.el-tabs__nav){width:100%}.container-tabs :deep(.el-tabs__item){height:34px;flex:1;padding:0 8px;font-size:10px}.container-tabs :deep(.el-tabs__content){overflow:visible}.container-tabs :deep(.el-input__inner),.container-tabs :deep(.el-select__placeholder),.container-tabs :deep(.el-button),.container-tabs :deep(.el-checkbox__label){font-size:10px}.config-grid,.resource-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 14px}.config-grid.one{grid-template-columns:1fr}.config-grid label,.resource-grid label,.probe-fields label{display:flex;min-width:0;flex-direction:column;gap:4px;font-weight:600}.config-grid .wide,.probe-fields .wide{grid-column:1/-1}.list-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:5px;font-weight:600}.list-row,.reference-row,.mount-row{display:grid;align-items:center;gap:5px;margin-top:5px}.list-row{grid-template-columns:minmax(0,1fr) 10px minmax(0,1fr) 24px}.reference-row{grid-template-columns:minmax(0,1fr) 70px 24px}.mount-row,.mount-head{display:grid;grid-template-columns:minmax(100px,1fr) minmax(130px,1.4fr) minmax(110px,1fr) 48px 30px;align-items:center;gap:5px}.mount-head{padding:5px 0;border-bottom:1px solid var(--line);color:var(--text-soft);font-weight:600}.probe-list{display:grid;gap:7px}.probe-list section,.command-card,.resource-stack section,.port-card{padding:8px;border:1px solid var(--line);border-radius:6px;background:#fff}.probe-list header,.command-card>header,.port-card>header{display:flex;align-items:center;justify-content:space-between}.probe-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin:7px 0}.command-card{min-height:72px}.indexed-row{display:grid;grid-template-columns:28px minmax(0,1fr) 24px;align-items:center;gap:5px;margin-top:5px}.indexed-row>span{display:grid;height:28px;place-items:center;border:1px solid var(--line);border-radius:5px;background:#fafafa;color:var(--primary)}.switch-row{display:flex;flex-direction:column;gap:7px;padding-top:7px}.env-tabs :deep(.el-tabs__item){justify-content:flex-start}.resource-stack{display:grid;gap:8px}.resource-stack section>header{margin-bottom:7px;padding-left:7px;border-left:2px solid var(--primary);font-weight:700}.port-card{margin-bottom:8px;border-color:color-mix(in srgb,var(--primary) 28%,var(--line))}.full-add{width:100%;border-color:var(--primary);color:var(--primary);background:var(--primary-soft)}@media(max-width:720px){.config-grid,.resource-grid,.probe-fields{grid-template-columns:1fr}.mount-row,.mount-head{grid-template-columns:1fr 1fr}.mount-row .el-button{justify-self:end}.mount-head{display:none}}
</style>
